t.script:
(function () {
    function parseExpiry(value) {
        if (!value) return null;
        var date = new Date(value);
        if (isNaN(date.getTime())) return null;
        return date;
    }

    function findCountdownForForm(form) {
        var parent = form.parentElement;
        while (parent) {
            var countdown = parent.querySelector('.hr-late-access-countdown');
            if (countdown) return countdown;
            parent = parent.parentElement;
        }
        return null;
    }

    function updateEmployeeLateAccessForms() {
        document.querySelectorAll('.hr-late-access-form').forEach(function (form) {
            var expiry = parseExpiry(form.getAttribute('data-expires-utc'));
            var countdown = findCountdownForForm(form);
            var submitButton = form.querySelector('button[type="submit"]');

            if (!expiry) {
                if (countdown) countdown.textContent = 'Expiry time unavailable. Please refresh.';
                return;
            }

            var diff = expiry.getTime() - Date.now();

            if (diff <= 0) {
                if (countdown) countdown.textContent = 'Expired. Please refresh the page or contact admin.';
                if (submitButton) {
                    submitButton.disabled = true;
                    submitButton.classList.add('disabled');
                    submitButton.innerHTML = '<i class="fa fa-lock me-2"></i> Access Expired';
                }
                return;
            }

            var totalSeconds = Math.floor(diff / 1000);
            var hours = Math.floor(totalSeconds / 3600);
            var minutes = Math.floor((totalSeconds % 3600) / 60);
            var seconds = totalSeconds % 60;

            var label = '';
            if (hours > 0) label += hours + 'h ';
            label += minutes + 'm ' + seconds + 's';

            if (countdown) countdown.textContent = label;
        });
    }

    function updateAdminLateAccessRows() {
        document.querySelectorAll('.hr-late-access-admin-row').forEach(function (row) {
            var expiry = parseExpiry(row.getAttribute('data-expires-utc'));
            if (!expiry) return;

            if (expiry.getTime() <= Date.now()) {
                var status = row.querySelector('.hr-late-access-status');
                var revokeForm = row.querySelector('.hr-late-access-revoke-form');

                if (status) {
                    status.textContent = 'expired';
                    status.classList.remove('bg-success');
                    status.classList.add('bg-secondary');
                }

                if (revokeForm) {
                    revokeForm.style.display = 'none';
                }
            }
        });
    }

    function updateAllLateAccessUI() {
        updateEmployeeLateAccessForms();
        updateAdminLateAccessRows();
    }

    updateAllLateAccessUI();
    setInterval(updateAllLateAccessUI, 1000);

    document.addEventListener('submit', function (event) {
        var form = event.target;
        if (!form.classList || !form.classList.contains('hr-late-access-form')) return;

        var expiry = parseExpiry(form.getAttribute('data-expires-utc'));
        if (expiry && expiry.getTime() <= Date.now()) {
            event.preventDefault();
            alert('Temporary access has expired. Please refresh the page or contact admin.');
        }
    });
})();

div.script:
(function () {
    function initTaskReportZoom() {
        var toolbar = document.getElementById('hrTaskReportZoomToolbar');
        if (!toolbar || toolbar.dataset.ready === '1') {
            return;
        }

        var container = toolbar.parentElement;
        if (!container) {
            return;
        }

        var table = container.querySelector('table');
        if (!table) {
            return;
        }

        toolbar.dataset.ready = '1';
        table.classList.add('hr-task-reports-table-zoom-table');

        var parent = table.parentElement;
        var safety = 0;
        while (parent && safety < 4) {
            parent.classList.add('hr-task-reports-table-wrap');
            parent = parent.parentElement;
            safety += 1;
        }

        var label = document.getElementById('hrTaskZoomLabel');
        var btnOut = document.getElementById('hrTaskZoomOut');
        var btnReset = document.getElementById('hrTaskZoomReset');
        var btnIn = document.getElementById('hrTaskZoomIn');
        var btnFit = document.getElementById('hrTaskZoomFit');

        function getSavedZoom() {
            var saved = parseFloat(localStorage.getItem('hrTaskReportsZoom') || '0.85');
            if (isNaN(saved)) {
                saved = 0.85;
            }
            return saved;
        }

        function setZoom(value) {
            value = Math.max(0.60, Math.min(1.20, value));
            value = Math.round(value * 100) / 100;

            table.style.zoom = value;
            table.style.webkitTransformOrigin = 'top left';

            if (label) {
                label.textContent = Math.round(value * 100) + '%';
            }

            localStorage.setItem('hrTaskReportsZoom', String(value));
        }

        if (btnOut) {
            btnOut.addEventListener('click', function () {
                setZoom(getSavedZoom() - 0.05);
            });
        }

        if (btnReset) {
            btnReset.addEventListener('click', function () {
                setZoom(0.85);
            });
        }

        if (btnIn) {
            btnIn.addEventListener('click', function () {
                setZoom(getSavedZoom() + 0.05);
            });
        }

        if (btnFit) {
            btnFit.addEventListener('click', function () {
                setZoom(0.75);
            });
        }

        setZoom(getSavedZoom());
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initTaskReportZoom);
    } else {
        initTaskReportZoom();
    }
})();

